import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xid9')
from h import *
P=[]
P.append(R(3651,"Mangkuk Kalkun Ala Asia","Mangkuk Kalkun Ala Asia adalah resep hidangan lengkap dengan sayuran rendah kalium, kalkun giling, daun ketumbar, Sriracha, jahe, dan coconut aminos sebagai pengganti kecap asin yang lebih tinggi natrium.","4","1-3/4 cangkir kalkun dan sayuran + 1/2 cangkir nasi",
["1 cangkir beras, mentah","1 bawang bombai kecil","1 paprika merah sedang","2 batang seledri sedang","3 siung bawang putih besar","1 sendok makan jahe segar","1 sendok makan minyak kanola","1 pon kalkun giling 7% lemak","1 sendok makan campuran bumbu bawang putih dan herba Mrs. Dash","8 ons kuntum brokoli beku","1/2 cangkir kaldu ayam rendah natrium","2 sendok makan gula merah","1-1/2 sendok makan coconut aminos","1 sendok teh saus cabai Sriracha","2 sendok makan daun ketumbar segar"],
["Siapkan nasi sesuai petunjuk kemasan. Keluarkan brokoli beku agar mencair. Potong dadu bawang bombai; iris seledri; iris paprika memanjang; cincang halus bawang putih, parut jahe, dan cincang daun ketumbar.","Siramkan minyak kanola ke dalam wajan antilengket besar dan panaskan dengan api sedang-besar. Masukkan kalkun dan masak hingga kecokelatan. Setengah jalan memasak, tambahkan bumbu herba Mrs. Dash. Setelah kalkun matang, angkat dari wajan.","Dalam wajan yang sama, masukkan bawang bombai, paprika, dan seledri lalu masak dengan api sedang selama 5 menit. Masukkan bawang putih dan jahe lalu masak 3 menit lagi.","Setelah sayuran lunak, masukkan brokoli beku dan aduk rata selama beberapa menit lagi.","Untuk membuat saus, campurkan kaldu, gula merah, coconut aminos, dan saus Sriracha dalam mangkuk kecil.","Masukkan kembali kalkun matang ke dalam wajan dan aduk bersama saus hingga tercampur.","Letakkan 1/2 cangkir nasi dalam mangkuk dan beri topping campuran kalkun dan sayuran. Tambahkan daun ketumbar cincang jika diinginkan. Selamat menikmati!"],
["Untuk membuat saus lebih kental, tambahkan 1 sendok teh tepung maizena.","Jika bumbu Mrs. Dash tidak tersedia, Anda dapat mencampurkan 1/2 sendok teh lada, 1 sendok teh bubuk bawang bombai, dan 1 sendok teh bubuk bawang putih.","Pasta jahe dapat digunakan sebagai pengganti jahe segar.","Untuk diet rendah protein, jika Anda menderita PGK dan tidak menjalani cuci darah, kurangi kalkun giling menjadi 1/2 pon. Protein berkurang menjadi 16 gram."],
["3 daging","1-1/2 pati","1-1/2 sayuran, kalium sedang"]))
P.append(R(3653,"Pancake Keju Cottage dan Krim Asam","Pasien cuci darah DaVita, Gloria, membagikan resepnya untuk Pancake Keju Cottage dan Krim Asam, sajian pancake tinggi protein dan rendah fosfor.","4","2 pancake ukuran 4″",
["2 butir telur besar","1/2 cangkir keju cottage butiran kecil","1/2 cangkir krim asam","1/8 sendok teh garam","1/2 cangkir tepung terigu serbaguna"],
["Kocok telur sebentar. Tambahkan keju cottage, krim asam, dan garam.","Aduk hingga tercampur; tidak akan halus.","Lipat tepung secara bertahap.","Tuangkan 1/4 cangkir adonan dengan jarak berjauhan ke dalam wajan panas yang diolesi minyak atau ke atas wajan datar antilengket.","Masak hingga kering dan kecokelatan di sekitar tepi. Balik dan masak sisi lainnya hingga kecokelatan."],
["Topping yang disarankan meliputi selai, jeli, atau buah kalengan. Tambahkan krim asam ekstra di atasnya jika diinginkan."],
["1 daging","1 pati","1 lemak"]))
P.append(R(3654,"Salsa Tomat Buatan Sendiri","Sedikit tomat masih dapat diterima dalam diet rendah kalium. Ahli gizi DaVita, Matilde dari Texas, menunjukkan cara memasukkan tomat. Cobalah resep Salsa Tomat Buatan Sendiri miliknya dengan hanya 103 mg kalium per porsi.","6","1/4 cangkir",
["1 bawang bombai sedang","1 tomat sedang","1/4 ikat daun ketumbar","1 cabai jalapeño kecil","1 jeruk nipis","1 sendok teh minyak zaitun","1/4 sendok teh garam","1/4 sendok teh lada hitam"],
["Cincang bawang bombai, tomat, daun ketumbar, dan jalapeño menjadi potongan kecil. Campurkan dalam mangkuk.","Peras jeruk nipis. Tambahkan air jeruk nipis, minyak zaitun, garam, dan lada ke campuran sayuran.","Diamkan salsa agar meresap selama 15 menit atau lebih.","Sajikan dengan keripik tortilla rendah natrium atau gunakan sebagai topping untuk ikan, ayam, daging, atau salad."],
["Gunakan bawang bombai merah, putih, atau kuning dalam resep ini.","Semakin keras tomatnya, semakin baik untuk resep ini.","Jalapeño bersifat opsional, atau Anda dapat menggunakan cabai pedas lain pilihan Anda.","Satu jeruk nipis menghasilkan sekitar 2 sendok makan air.","Garam kosher dan lada segar giling memberikan rasa yang lebih baik, jika tersedia.","Gunakan food processor untuk mencincang sayuran jika diinginkan."],
["1/2 sayuran, kalium sedang"]))
P.append(R(3655,"Buncis dengan Lobak Turnip","Berikut cara yang bagus untuk mendapatkan sayuran Anda. Resep Buncis dengan Lobak Turnip bergaya Selatan yang ramah ginjal ini kaya cita rasa. Mudah dibuat, cukup rebus dan tambahkan bumbu. Lezat.","8","1/2 cangkir",
["1 pon buncis segar","2 lobak turnip sedang","2 siung bawang putih","1 sendok makan mentega tanpa garam","1/2 sendok teh lada hitam","1/4 sendok teh garam","1/4 sendok teh paprika"],
["Buang ujung buncis dan potong menjadi potongan 1-1/2″. Kupas lobak turnip dan potong dadu masing-masing menjadi 8 bagian. Cincang halus bawang putih.","Letakkan sayuran dan bawang putih dalam panci berukuran sedang. Tutup dengan 3 cangkir air dan didihkan. Kecilkan ke api sedang dan masak tanpa ditutup selama 15 menit.","Angkat panci dari api dan buang airnya. Tambahkan mentega, lada, dan garam. Aduk perlahan agar bumbu tercampur dengan sayuran. Sajikan panas.","Pindahkan ke piring saji dan taburi dengan paprika."],
["Tambahkan sedikit saus pedas jika Anda menyukai sayuran pedas."],
["1 sayuran, kalium sedang","1/2 lemak"]))
P.append(R(3658,"Ayam Loyang dengan Buncis dan Kentang","Makan malam ayam jadi lebih mudah. Cobalah Ayam Loyang dengan Buncis dan Kentang dari ahli gizi DaVita, Jackie. Mudah dibuat dan hanya satu loyang yang perlu dibersihkan.","4","1/4 resep",
["2 cangkir kentang merah","1 sendok teh minyak zaitun","16 ons potongan ayam panjang, mentah","10 ons buncis potong beku","4 sendok makan mentega tanpa garam","1 sendok makan campuran kering dressing Italia"],
["Panaskan oven terlebih dahulu hingga 400˚ F. Potong kentang menjadi potongan seukuran suapan. Lihat tips bermanfaat untuk petunjuk pengurangan kalium jika diperlukan. Aduk kentang dengan 1 sendok teh minyak zaitun.","Semprot loyang 9 x 13 inci dengan semprotan masak. Letakkan potongan ayam mentah di sepertiga loyang. Letakkan kentang di sepertiga loyang berikutnya. Terakhir, tata buncis beku di sepertiga loyang terakhir.","Lelehkan mentega dan siramkan ke seluruh loyang berisi ayam, kentang, dan buncis. Taburkan campuran kering dressing Italia ke seluruh loyang.","Panggang selama 20 sampai 30 menit. Periksa kematangan ayam setelah 20 menit."],
["Analisis gizi didasarkan pada kentang yang telah direbus untuk mengurangi kalium. Jika tidak, kandungan kalium adalah 766 mg per porsi.","Untuk mengurangi kalium pada kentang: Potong kentang. Letakkan dalam panci besar dan tutup seluruhnya dengan air. Didihkan, lalu tiriskan. Isi kembali air di atas kentang hingga terendam 1 inci. Didihkan lagi dan rebus selama 10 menit. Tiriskan dan aduk dengan 1 sendok teh minyak zaitun sebelum ditambahkan ke loyang.","Berat kemasan potongan dada ayam mentah bervariasi. Umumnya beratnya antara 14-16 ons. Ada 16 ons dalam 1 pon.","Ada sekitar 2 sendok makan campuran kering dressing Italia dalam satu sachet 19 gram. Pilih campuran kering dengan natrium serendah mungkin. Berhati-hatilah, penggunaan campuran kering yang terlalu banyak akan meningkatkan kandungan natrium hidangan.","Simpan sisa campuran dressing Italia untuk resep lain atau campurkan dengan krim asam sebagai dip sayuran."],
["3 daging","1 pati","1 sayuran, kalium sedang"]))
P.append(R(3659,"Saus Alfredo Krimi","Buatlah saus alfredo krimi ini untuk makan malam Anda. Resep DaVita lezat, ramah ginjal, dan disumbangkan oleh ahli gizi DaVita.","10","55 gram, sekitar 2 sendok makan",
["2-1/4 sendok makan susu bubuk tanpa lemak","3/4 cangkir air","1/4 cangkir mentega tanpa garam","1/2 sendok teh lada putih","6 ons keju krim","1 siung bawang putih","1/4 sendok teh garam merah muda Himalaya","4 ons keju Parmigiano-Reggiano","1/2 sendok teh bumbu Emeril’s® Italian Essence"],
["Tumis bawang putih dalam mentega.","Tambahkan bahan-bahan lainnya. Masak dengan api kecil hingga mencapai tekstur halus.","Timbang saus yang sudah jadi dan bagi dengan 10 untuk menentukan berat ukuran porsi."],
["Simpan porsi ekstra di freezer dalam cangkir porsi 2 ons."],
["1 susu","2 lemak"]))
P.append(R(3660,"Kembang Kol dengan Saus Bawang Putih","Ahli gizi ginjal DaVita, Diana, memiliki resep Kembang Kol dengan Saus Bawang Putih yang cepat dan mudah serta digemari. Bawang putih, madu, dan cuka sari apel berpadu menciptakan sensasi rasa yang mengubah kembang kol ramah ginjal menjadi hidangan sayuran yang dapat dinikmati seluruh keluarga.","8","1/2 cangkir",
["4 cangkir kuntum kembang kol","2 siung bawang putih","1 sendok makan minyak zaitun","4 sendok teh madu","3 sendok makan cuka sari apel","1 sendok makan peterseli segar"],
["Dalam panci besar dengan rak pengukus, kukus kembang kol di atas air mendidih selama 8 sampai 10 menit atau hingga empuk-renyah (tutup dengan penutup saat mengukus).","Dalam panci kecil, masak bawang putih cincang dalam minyak zaitun selama 30 detik lalu angkat panci dari api.","Aduk madu, cuka sari apel, dan peterseli cincang. Kembalikan panci ke api hingga saus panas.","Pindahkan kembang kol kukus ke piring saji.","Siramkan saus di atas kembang kol panas dan aduk hingga terlapisi."],
["Ini adalah cara yang cepat dan mudah untuk menambahkan sayuran bergizi ke dalam hidangan Anda."],
["1 sayuran, kalium rendah","1/2 lemak"]))
P.append(R(3663,"Pavlova dengan Stroberi","Cobalah resep Pavlova dengan Stroberi yang lezat dan ramah ginjal dari ahli gizi DaVita, Brenda dari Washington. Ia menggunakan beberapa makanan regional favoritnya sehingga Anda dapat membuat hidangan lezat yang sesuai untuk pasien cuci darah dengan cita rasa luar biasa dari Pacific Northwest.","8","1/8 (iris)",
["6 putih telur besar","1/8 sendok teh garam","2 cangkir + 2 sendok makan gula pasir","1-1/2 sendok teh cuka","2-1/2 sendok teh ekstrak vanila","8 ons krim kocok kental (heavy whipping cream)","4 cangkir stroberi segar, diiris"],
["Panaskan oven terlebih dahulu hingga 300º F. Keluarkan putih telur agar mencapai suhu ruang. Iris stroberi dan sisihkan.","Kocok putih telur dengan garam pada kecepatan tinggi hingga terbentuk puncak lunak. Tambahkan 2 cangkir gula, 1 sendok makan setiap kali, kocok rata setelah setiap penambahan. Lipat perlahan cuka dan 1-1/2 sendok teh vanila.","Ratakan campuran ke atas loyang kue bulat 8” atau loyang pizza yang tidak diolesi minyak. Haluskan bagian atasnya.","Panggang selama 45 menit. Matikan oven dan biarkan cangkang mengeras selama 1 jam dengan pintu oven tertutup. Keluarkan dari oven dan biarkan dingin sepenuhnya.","Untuk krim kocok, letakkan mangkuk dan whisk di freezer selama 10-15 menit. Masukkan gula, krim kocok kental, dan sisa 1 sendok teh vanila ke dalam mangkuk lalu kocok hingga kaku. (Dapat dilakukan dengan mixer tangan, stand mixer, atau secara manual.)","Isi cangkang Pavlova dengan krim kocok dan taruh irisan stroberi di atasnya."],
["Saat mengocok putih telur, mulailah dengan kecepatan rendah hingga sedang sampai setengah mengembang. Pada tahap ini tambahkan sejumput garam atau cream of tartar dan naikkan mixer ke kecepatan tinggi. Hasilnya adalah putih telur kocok yang lebih stabil dan membutuhkan waktu lebih singkat untuk dikocok.","Tidak dianjurkan bagi penderita diabetes karena kandungan karbohidratnya yang tinggi."],
["1/2 daging","1/2 buah, kalium rendah","1 lemak","2 kalori tinggi"]))
P.append(R(3664,"Vinaigrette Raspberry Jeruk Nipis","Tidak heran vinaigrette raspberry jeruk nipis ini menjadi favorit andalan ahli gizi ginjal Judy dari Pennsylvania. Raspberry segar bersama cuka raspberry dan selai raspberry menambahkan cita rasa buah beri yang manis yang melengkapi sayuran salad tanpa menambah natrium.","6","2 sendok makan",
["1/4 cangkir air jeruk nipis segar","2 sendok makan cuka raspberry","2 sendok makan raspberry segar","2 sendok makan selai raspberry","1/2 sendok teh tarragon segar","2 sendok teh gula","1/4 sendok teh garam kosher","1/4 cangkir minyak kanola"],
["Haluskan raspberry dan cincang tarragon.","Kocok bersama 7 bahan pertama.","Kocok perlahan minyak hingga tercampur rata. Sajikan.","Simpan sisa dressing dalam botol kaca yang tertutup rapat di lemari es hingga siap disajikan. Awet hingga satu minggu."],
["Dua jeruk nipis segar menghasilkan sekitar 1/4 cangkir air jeruk nipis.","Siramkan 2 sendok makan dressing di atas sayuran salad dengan topping raspberry segar.","Gunakan selai rendah gula atau olesan buah sebagai pengganti untuk mengurangi karbohidrat menjadi 5 gram.","Gunakan 1/4 sendok teh tarragon kering jika yang segar tidak tersedia.","Minyak biji anggur adalah pengganti minyak kanola yang rasanya enak."],
["1/2 kalori tinggi","2 lemak"]))
P.append(R(3665,"Cutlet Sayuran","Cutlet Sayuran adalah resep ramah ginjal yang kaya cita rasa. Anda juga dapat menambahkan Chutney Ketumbar di atasnya sebagai hiasan yang lezat.","6","2 cutlet",
["1 cangkir wortel","2 cangkir kubis","2 cangkir buncis beku potong memanjang","1/4 sendok teh garam","1 sendok teh bubuk jinten","1 sendok teh bubuk ketumbar","1 sendok teh bubuk cabai merah","1/2 cangkir tepung terigu putih serbaguna","4 lembar roti tawar","1/4 cangkir daun ketumbar segar","1/2 sendok teh air jeruk nipis","2 sendok makan minyak kanola"],
["Cairkan dan cincang buncis. Parut wortel, kubis, dan daun ketumbar.","Rendam irisan roti dalam air dan tiriskan dengan meremasnya di antara kedua telapak tangan.","Dalam panci sedang, tutup kubis dan wortel dengan air lalu rebus selama 10 menit. Tambahkan buncis cincang dan masak hingga benar-benar matang. Buang kelebihan air dan dinginkan.","Tambahkan rempah, tepung, irisan roti, daun ketumbar, dan air jeruk nipis ke sayuran lalu aduk rata.","Bentuk 12 bola dan pipihkan masing-masing menjadi patty seukuran burger kecil.","Panaskan wajan dengan api sedang. Tambahkan minyak dan letakkan patty di wajan, dua atau tiga sekaligus tanpa berdesakan. Balik patty saat sudah matang, sekitar 2-3 menit untuk setiap sisi.","Sajikan panas."],
["Saran penyajian: Sajikan dalam roti bun dengan mayones, selada, dan bawang bombai, atau sajikan tanpa roti dengan topping Chutney Ketumbar atau saus celup favorit Anda.","Bekukan atau simpan sisa cutlet di lemari es untuk hidangan atau camilan cepat nanti."],
["1 pati","1 sayuran, kalium sedang","1 lemak"]))
P.append(R(3669,"Labu Nanas","Hidangan labu ramah ginjal ini memiliki keunikan tersendiri. Nanas memberikan sisi manis sehingga dapat disajikan sebagai pendamping hidangan apa pun.","6","1/2 cangkir",
["1 pon labu musim panas","1 pon labu zucchini","1/2 cangkir paprika hijau","8 ons nanas cincang tanpa pemanis","1-1/2 sendok teh kayu manis bubuk","1/3 cangkir gula merah padat","1 sendok makan mentega, dipotong kecil-kecil"],
["Potong labu dan zucchini menjadi kubus 1 inci, potong dadu paprika hijau. Letakkan labu dalam slow cooker 3-1/2 atau 4 quart.","Dalam mangkuk kecil, campurkan nanas, paprika hijau, kayu manis, gula merah, dan mentega.","Sendokkan campuran di atas labu dan aduk rata.","Tutup dan masak pada pengaturan api rendah selama 6-7 jam atau hingga labu empuk. Aduk perlahan hingga tercampur.","Sajikan segera."],
["Penderita diabetes dapat menggunakan pengganti gula merah Splenda® dalam jumlah yang sama."],
["1-1/2 sayuran, kalium tinggi","1/2 lemak","1 kalori tinggi"]))
P.append(R(3670,"Putih Telur Polos","Tidak ada yang polos dari resep Putih Telur Polos ini. Ini adalah pengganti protein yang bagus bagi penderita diabetes yang menjalani cuci darah.","1","1 cangkir",
["8 ons putih telur cair pasteurisasi","1 sendok teh minyak"],
["Masukkan putih telur cair pasteurisasi ke dalam wajan yang sudah diolesi minyak.","Masak dengan api sedang, tutup atau balik."],
["Bumbui dengan campuran bumbu herba rendah natrium favorit Anda.","Gunakan mentega sebagai pengganti minyak untuk cita rasa tambahan.","Buat sandwich atau wrap, atau santap sebagai pengganti daging dengan sayuran dan makanan pati."],
["4 daging"]))
P.append(R(3672,"Alternatif Susu Vanila","Meskipun banyak pengganti susu yang dijual, mengapa tidak membuat sendiri pengganti rendah kalium dan rendah fosfor?","8","8 ons",
["6-1/2 cangkir air dingin","8 ons krim kocok kental (heavy whipping cream)","6 sendok takar bubuk whey protein vanila EAS® 100%"],
["Campurkan 1/4 sampai 1/2 resep sekaligus dalam blender (tergantung ukuran blender) selama 20 detik agar bubuk protein tercampur rata.","Sajikan dingin dan selamat menikmati!"],
["Resep ini menghasilkan sekitar 1/2 galon. Simpan sisa minuman dalam teko tertutup.","Bubuk whey protein EAS yang digunakan dalam analisis gizi mengandung 26 gram protein untuk 2 sendok takar. Jika Anda menggunakan merek whey protein lain, sesuaikan jumlahnya untuk menyediakan sekitar 156 gram protein untuk seluruh resep. Tanyakan kepada ahli gizi Anda tentang pilihan bubuk protein lainnya.","Gunakan bubuk whey protein stroberi atau cokelat untuk minuman dengan rasa berbeda."],
["1 pengganti susu"]))
P.append(R(3675,"Kotak Ayam","Resep Kotak Ayam yang ramah bagi pasien cuci darah ini disumbangkan oleh ahli gizi ginjal DaVita, Lori dari Pennsylvania, yang sangat paham soal cita rasa dan kepraktisan.","4","1 kotak",
["3/4 pon dada ayam, dengan tulang, dengan kulit","3 sendok makan keju krim","1 sendok makan mentega tanpa garam","1/2 cangkir kuntum brokoli","1 kemasan roti gulung Pillsbury Crescent Original®"],
["Panaskan oven terlebih dahulu hingga 350° F. Keluarkan keju krim agar melunak. Lelehkan mentega.","Masak, tiriskan, dan cincang brokoli.","Rebus dada ayam hingga matang; tiriskan, buang kulit dan tulang, lalu potong dadu.","Campurkan ayam, keju krim yang sudah lunak, mentega leleh, dan brokoli.","Buka roti gulung crescent dan bentuk persegi panjang dari 2 gulungan. Tekan sambungan untuk merekatkan dan regangkan persegi panjang.","Letakkan 1/4 campuran ayam di tengah; lipat tepinya menyilang untuk membuat turnover. Tekan tepinya untuk merekatkan.","Panggang selama 25 sampai 30 menit atau hingga roti berwarna cokelat."],
["Sesekali periksa Kotak Ayam saat dipanggang dalam oven agar tidak terlalu cokelat.","Ini adalah hidangan utama yang lebih tinggi natrium. Untuk menjaga natrium tetap terkendali, lengkapi hidangan dengan menu rendah natrium seperti salad, dressing rendah natrium, dan buah.","Tulang dan kulit ayam menambah cita rasa saat dimasak. Empat belas ons dada ayam tanpa tulang dan tanpa kulit dapat digunakan sebagai pengganti dada ayam bertulang jika diinginkan.","Bekukan atau simpan di lemari es kaldu dari merebus ayam untuk digunakan nanti dalam resep yang membutuhkan kaldu ayam rendah natrium.","Jika menggunakan keju krim bebas lemak, lemak berkurang menjadi 16 gram dan natrium 577 mg."],
["2 daging","1-1/2 pati","2 lemak"]))
P.append(R(3677,"Salad Tuna Albacore Rendah Natrium","Dressing Thousand Island dan mustard kuning adalah bahan kejutan dalam resep Salad Tuna Albacore Rendah Natrium yang lezat ini.","2","1/2 resep",
["1 sendok teh bawang bombai","1 sendok teh seledri","2-2/3 ons tuna putih albacore, rendah natrium, dikemas dalam air","1 sendok makan dressing Thousand Island","2 sendok makan mayones","1/2 sendok teh mustard kuning"],
["Cincang halus seledri dan bawang bombai.","Dalam mangkuk kecil, campurkan semua bahan.","Timbang salad yang sudah jadi dan bagi dengan 2 untuk menentukan berat ukuran porsi."],
["Virgil lebih menyukai StarKist® Low Sodium Albacore White Tuna karena kandungan natriumnya rendah. Periksa di Target jika Anda tidak dapat menemukannya di toko kelontong setempat."],
["1 daging","1-1/2 lemak"]))
save(3,P)
